const $=(s,r=document)=>r.querySelector(s);
const escapar=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const linkSeguro=u=>{if(typeof u!=='string'||!u.trim())return'';try{const p=new URL(u,location.origin);return['http:','https:'].includes(p.protocol)?p.href:''}catch{return''}};
const semAcento=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const fontesIdiomas=[['apostilas','Apostilas e cursos indígenas completos'],['openalex','OpenAlex · PDFs abertos'],['bloom','Bloom Library · livros multilíngues'],['opentextbook','Open Textbook Library · PDFs'],['curt','Biblioteca Digital Curt Nimuendajú'],['museu','Museu Nacional dos Povos Indígenas'],['isa','Instituto Socioambiental · ISA'],['ailla','AILLA'],['olac','OLAC'],['bdtd','BDTD / IBICT'],['tatoeba','Tatoeba'],['panlex','PanLex'],['wiktionary','Wikcionário / Wiktionary'],['lingualibre','Lingua Libre'],['fsi','FSI Language Courses'],['dli','DLI GLOSS'],['merlot','MERLOT World Languages'],['libretexts','LibreTexts'],['elar','ELAR'],['dobes','DOBES / The Language Archive'],['kaipuleohone','Kaipuleohone'],['corsal','CoRSAL'],['coerll','COERLL'],['oercommons','OER Commons'],['livelingua','Peace Corps / Live Lingua']].map(([id,nome])=>({id,nome}));
const estado={consulta:'',resultados:[],porFonte:{},buscando:false,token:0};
function abrirIdiomas(){const painel=$('#painel');if(painel?.open)painel.close();const d=$('#idiomas');if(!d.open)d.showModal();setTimeout(()=>$('#campo-idiomas')?.focus(),40);renderizar()}
function capaSimbolica(item){const simbolo=item.fonte==='apostilas'?'PDF':item.fonte==='openalex'?'PDF':item.fonte==='bloom'?'BL':item.fonte==='opentextbook'?'PDF':item.tipo?.includes('Áudio')?'◉':item.tipo?.includes('Dicionário')?'Aa':item.tipo?.includes('Curso')?'A':item.tipo?.includes('Gramática')?'G':'L';return`<div class="sem-capa" aria-hidden="true">${escapar(simbolo)}</div>`}
function peso(item){const s=`${item.tipo||''} ${item.provedor||''}`.toLowerCase();if(item.fonte==='apostilas'&&s.includes('apostila completa'))return-100;if(item.fonte==='apostilas'&&s.includes('curso completo'))return-95;if(item.fonte==='apostilas'&&s.includes('manual completo'))return-90;if(item.fonte==='apostilas'&&s.includes('gramática pedagógica'))return-85;if(item.fonte==='apostilas')return-80;if(s.includes('apostila completa'))return-70;if(s.includes('curso completo'))return-60;if(item.fonte==='openalex')return-3;if(item.fonte==='bloom')return-2;if(item.fonte==='opentextbook')return-1;if(s.includes('curso / material'))return 1;if(s.includes('livro / apostila'))return 2;if(s.includes('gramática'))return 3;if(s.includes('dicionário'))return 4;if(s.includes('frase'))return 5;if(s.includes('áudio'))return 6;return 7}
function normalizarResultados(lista){const vistos=new Set(),saida=[];for(const item of Array.isArray(lista)?lista:[]){const chave=(item.url||'')+'|'+(item.titulo||'');if(!item?.titulo||vistos.has(chave))continue;vistos.add(chave);saida.push(item)}return saida.sort((a,b)=>{const pa=peso(a),pb=peso(b);if(pa!==pb)return pa-pb;return Number(a.prioridade||999)-Number(b.prioridade||999)})}
function combinarPorFonte(...grupos){const saida={};for(const grupo of grupos)for(const[id,d]of Object.entries(grupo||{})){if(!saida[id])saida[id]={...d};else saida[id]={...saida[id],...d,quantidade:Math.max(saida[id].quantidade||0,d.quantidade||0),portal:Boolean(saida[id].portal&&d.portal),erro:Boolean(saida[id].erro&&d.erro)}}return saida}
function pdfOpenAlex(x){const locais=[x?.best_oa_location,x?.primary_location,...(Array.isArray(x?.locations)?x.locations:[])].filter(Boolean);for(const l of locais){const u=linkSeguro(l?.pdf_url);if(u&&l?.is_oa!==false)return u}const oa=linkSeguro(x?.open_access?.oa_url);return oa&&/\.pdf(?:$|[?#])/i.test(oa)?oa:''}
function resultadosOpenAlex(d){const itens=Array.isArray(d?.results)?d.results:[],saida=[];for(const x of itens){const pdf=pdfOpenAlex(x);if(!pdf)continue;const id=String(x?.id||'').split('/').pop();if(!id)continue;const autores=(Array.isArray(x?.authorships)?x.authorships:[]).map(a=>a?.author?.display_name).filter(Boolean);saida.push({id:`openalex:${id}`,fonte:'openalex',provedor:'OpenAlex · PDF aberto',titulo:String(x?.display_name||x?.title||'Sem título'),descricao:[autores.slice(0,4).join(' · '),x?.publication_year,x?.type].filter(Boolean).join(' · '),tipo:'PDF aberto',url:pdf,modo:'pdf',idioma:x?.language||'',audio:null})}return saida}
function resultadosApostilas(d,q){const lista=Array.isArray(d?.materiais)?d.materiais:[],n=semAcento(q),generica=/(apostila|apostilas|curso|cursos|pdf|material).*(indigena|indigenas)|(indigena|indigenas).*(apostila|apostilas|curso|cursos|pdf|material)/.test(n),saida=[];for(const x of lista){const chaves=(Array.isArray(x.chaves)?x.chaves:[]).map(semAcento),idioma=semAcento(x.idioma),titulo=semAcento(x.titulo);if(!generica&&!chaves.some(c=>n.includes(c)||c.includes(n))&&!idioma.includes(n)&&!titulo.includes(n))continue;saida.push({...x,fonte:'apostilas',provedor:'Biblioteca Livre · acervo didático indígena',modo:'curso',audio:null});if(saida.length>=100)break}return saida}
function renderizar(){const area=$('#resultados-idiomas');if(!area)return;const contagens={};for(const r of estado.resultados)if(r.modo!=='portal')contagens[r.fonte]=(contagens[r.fonte]||0)+1;const estados=fontesIdiomas.map(f=>({id:f.id,nome:f.nome,dados:estado.porFonte[f.id],quantidade:contagens[f.id]||0}));const conectadas=estados.filter(x=>x.dados&&!x.dados.portal&&!x.dados.erro).length,portais=estados.filter(x=>x.dados?.portal).length,erros=estados.filter(x=>x.dados?.erro).length;$('#status-idiomas').textContent=estado.consulta?`${estado.resultados.length} ${estado.resultados.length===1?'material encontrado':'materiais encontrados'} · ${fontesIdiomas.length} fontes especializadas consultadas${conectadas?` · ${conectadas} com resultados diretos`:''}${portais?` · ${portais} catálogos oficiais`:''}${erros?` · ${erros} falha${erros===1?'':'s'} temporária${erros===1?'':'s'}`:''}`:'Pesquise um idioma, povo, gramática, curso, palavra ou material de estudo.';const chips=$('#fontes-idiomas-status');chips.hidden=!estado.consulta&&!estado.buscando;chips.innerHTML=estados.map(x=>`<span class="fonte-chip ${x.dados?.erro?'erro':x.dados?'ok':'espera'}"><b>${escapar(x.nome)}</b><i>${x.dados?.erro?'×':x.dados?.portal?'↗':x.dados?x.quantidade:'…'}</i></span>`).join('');const carga=$('#carregando-idiomas');carga.hidden=!estado.buscando;carga.setAttribute('aria-hidden',String(!estado.buscando));if(estado.buscando){$('#carregando-idiomas-titulo').textContent='Percorrendo apostilas completas, cursos, PDFs e acervos linguísticos…';$('#carregando-idiomas-fonte').textContent='Apostilas e cursos completos aparecem primeiro; depois entram OpenAlex, Bloom e as demais fontes.';$('#progresso-idiomas-barra').style.width='62%';$('#progresso-idiomas-texto').textContent=`Consultando ${fontesIdiomas.length} fontes especializadas`}else if(estado.consulta){$('#progresso-idiomas-barra').style.width='100%';$('#progresso-idiomas-texto').textContent=`${fontesIdiomas.length} de ${fontesIdiomas.length} fontes consultadas`}area.setAttribute('aria-busy',String(estado.buscando));if(!estado.consulta&&!estado.buscando){area.innerHTML='<div class="estado-vazio"><h3>Uma biblioteca só para idiomas.</h3><p>Procure por Nheengatu, Guarani, Tukano, Tupi Antigo, Baniwa, Tikuna, Kaingang, Mandarim, Latim, Japonês, Árabe ou pelo nome de uma gramática, curso ou apostila.</p></div>';return}if(estado.buscando&&!estado.resultados.length){area.innerHTML='<div class="estado-vazio"><h3>Abrindo apostilas, cursos e arquivos…</h3><p>Os materiais didáticos completos são priorizados antes dos PDFs acadêmicos e dos catálogos gerais.</p></div>';return}area.innerHTML=estado.resultados.length?estado.resultados.map(item=>{const url=linkSeguro(item.url),audio=linkSeguro(item.audio),portal=item.modo==='portal';return`<article class="resultado">${capaSimbolica(item)}<div><h3>${escapar(item.titulo)}</h3><p>${escapar(item.descricao||'Material para estudo de idiomas.')}</p><div class="meta-livro"><span>${escapar(item.tipo||'Material de idioma')}</span><span>${escapar(item.provedor||'Fonte especializada')}</span>${item.idioma?`<span>${escapar(item.idioma)}</span>`:''}<span class="tipo-acesso ${portal?'catalogo':'integral'}">${portal?'Busca no catálogo':/pdf/i.test(item.tipo||'')?'PDF aberto':'Resultado direto'}</span></div><div class="acoes-resultado">${url?`<a class="ler" href="${escapar(url)}" target="_blank" rel="noopener noreferrer">${portal?'Pesquisar na fonte':/pdf/i.test(item.tipo||'')?'Abrir PDF':'Abrir material'} ↗</a>`:''}${audio?`<a href="${escapar(audio)}" target="_blank" rel="noopener noreferrer">Ouvir áudio ↗</a>`:''}</div></div></article>`}).join(''):`<div class="estado-vazio"><h3>Nenhum material apareceu nesta tentativa.</h3><p>Tente o nome do idioma em português e depois no nome original, ou pesquise por “gramática”, “curso”, “dicionário” ou “apostila” junto do idioma.</p></div>`}
async function pesquisar(q){q=String(q||'').trim();estado.consulta=q;estado.resultados=[];estado.porFonte={};const token=++estado.token;if(!q){estado.buscando=false;renderizar();return}estado.buscando=true;renderizar();try{const c=new AbortController(),timer=setTimeout(()=>c.abort(),18000),buscar=async rota=>{try{const separador=rota.includes('?')?'&':'?';const r=await fetch(`${rota}${separador}q=${encodeURIComponent(q)}`,{signal:c.signal,headers:{Accept:'application/json'}});if(!r.ok)return null;return await r.json()}catch{return null}},buscarJson=async rota=>{try{const r=await fetch(rota,{signal:c.signal,headers:{Accept:'application/json'}});if(!r.ok)return null;return await r.json()}catch{return null}},respostas=await Promise.all([buscarJson('/dados/apostilas-indigenas.json?v=20260917a'),buscarJson('/dados/apostilas-indigenas-extra.json?v=20260917b'),buscar('/api/acervos-gratuitos?fonte=openalex'),buscar('/api/idiomas'),buscar('/api/idiomas-cursos')]);clearTimeout(timer);if(token!==estado.token)return;const[apostilasBase,apostilasExtra,openalex,...outras]=respostas,validas=outras.filter(Boolean),catalogoApostilas={materiais:[...(Array.isArray(apostilasBase?.materiais)?apostilasBase.materiais:[]),...(Array.isArray(apostilasExtra?.materiais)?apostilasExtra.materiais:[])]};if(!catalogoApostilas.materiais.length&&!openalex&&!validas.length)throw Error();const itensApostilas=resultadosApostilas(catalogoApostilas,q),itensOpenAlex=resultadosOpenAlex(openalex),demais=validas.flatMap(d=>d.resultados||[]);estado.resultados=normalizarResultados([...itensApostilas,...itensOpenAlex,...demais]);estado.porFonte=combinarPorFonte(...validas.map(d=>d.porFonte||{}));estado.porFonte.apostilas={nome:'Apostilas e cursos indígenas completos',quantidade:itensApostilas.length,portal:false,erro:!apostilasBase&&!apostilasExtra};estado.porFonte.openalex={nome:'OpenAlex · PDFs abertos',quantidade:itensOpenAlex.length,portal:false,erro:!openalex};for(const f of fontesIdiomas)if(!estado.porFonte[f.id])estado.porFonte[f.id]={nome:f.nome,quantidade:0,portal:false,erro:false}}catch{if(token!==estado.token)return;estado.resultados=[];estado.porFonte={};for(const f of fontesIdiomas)estado.porFonte[f.id]={nome:f.nome,quantidade:0,portal:false,erro:true}}if(token!==estado.token)return;estado.buscando=false;renderizar()}
function injetarMenu(){const conteudo=$('#conteudo-painel'),explorar=conteudo?.querySelector('[data-acao="explorar"]');if(!explorar||conteudo.querySelector('[data-idiomas="abrir"]'))return;const bloco=document.createElement('div');bloco.className='item-painel';bloco.innerHTML='<button data-idiomas="abrir"><strong>Idiomas</strong><small>Cursos, apostilas, línguas indígenas e idiomas do mundo ↗</small></button>';explorar.closest('.item-painel')?.after(bloco)}
